A: See documentation : Currently, the following algorithms can make use of multi-threading: general dense matrix - matrix products PartialPivLU row-major-sparse * dense vector/matrix products ConjugateGradient with Lower|Upper as the UpLo template parameter. BiCGSTAB with a row-major sparse matrix format. LeastSquaresConjugateGradient Only the row-major sparse matrix format is supported for multi-threading. Therefore, you will need to have: Eigen::SparseMatrix<double, Eigen::RowMajor> A(N, N);
Eigen::BiCGSTAB<Eigen::SparseMatrix<double, Eigen::RowMajor>> solver; I have noticed that inserting elements to the matrix takes longer than calculating the solution. Since the prior is sequential, it may not be feasible to observe the parallelism. You can increase the maximum number of solver iterations (i.e solver.setMaxIterations(1e9) ) to force solution to take longer (thus easier to observe CPU occupation). You can also print checkpoints to observe which part of your code is executing at that moment. For example: void eigen_test(int N)
{
    Eigen::SparseMatrix<double, Eigen::RowMajor> A(N, N);
    Eigen::SparseMatrix<double> b(N, 1);
    Eigen::SparseMatrix<double> x(N, 1);
    Eigen::BiCGSTAB<Eigen::SparseMatrix<double, Eigen::RowMajor>> solver;

    solver.setMaxIterations(1e9);

    A.reserve(5*N);
    b.reserve(N);
    x.reserve(N);

    std::cout << "checkpoint: insert elems..." << std::endl;

    for(int i=0; i<N; i++)
    {   
        b.insert(i, 0) = 20.0;

        for(int j=(i-2); j<=(i+2); j++)
        {
            if(j == i)
            {
                A.insert(j, i) = 10.0;
            }
            else if((j >= 0) && (j < N))
            {
                A.insert(j, i) = 5.0;
            }
        }
    }

    std::cout << "checkpoint: find solution..." << std::endl;

    solver.compute(A);
    x = solver.solve(b);

    std::cout << "checkpoint: done!" << std::endl;
}

A: Courtesy to @Homer512 it's now working. If anyone ever encounters this issue again, here is how I solved it! const int per_task = 2;

void apply_grayscale(uint8_t* input_buffer,uint8_t* output_buffer,uint16_t image_w,uint16_t image_h){
  size_t pixel_row_size = 3 * image_w;
  if(pixel_row_size % 4)
      pixel_row_size += 4 - (pixel_row_size % 4);


  #pragma omp parallel
  #pragma omp single
  {
      for(uint16_t i = 0; i < image_h; i+=per_task) {
          #pragma omp task
          {
              for (int j = 0; j < per_task && i + j < image_h; j++) {
                  uint8_t* current_input_buffer = input_buffer + ((i + j) * pixel_row_size);
                  uint8_t* current_output_buffer = output_buffer + ((i + j) * pixel_row_size);            
                  grayscale_row(current_input_buffer,current_output_buffer,image_w);
              }
          }
      }   
  }
}
}

