A: As pointed out by @Daniel Langr your form of loop test is not supported. It has to be a canonical loop form. For more details see 2.9.1 Canonical Loop Form of the OpenMP specification. Taking the square root of both sides of comparison you can change it to a supported form: const int end_p=sqrt(n);
#pragma omp for 
for (int p = 2; p <= end_p; p++) Note that your code has other error as well: each thread will create a private prime array and work on their private copy, so you obtain incorrect result. You can correct it by using shared prime array and atomic read and write operations: void SieveOfEratosthenes(int n)
{    
    bool prime[n + 1];
    memset(prime, true, sizeof(prime));

    const int end_p=sqrt(n);
    #pragma omp parallel for 
    for (int p = 2; p <= end_p; p++)
    {
        bool prime_p;
        #pragma omp atomic read
        prime_p=prime[p];
        if (prime_p == true)
        {
            for (int i = p * p; i <= n; i += p)
            {
                #pragma omp atomic write
                prime[i] = false;
            }
        }
    }

    for (int p = 2; p <= n; p++)
        if (prime[p])
            printf("%d  ", p);

}

