A: Yes, you can obtain a benefit for large problems using OpenMP here.  The benefit will be realized when the input is large enough to be memory-bandwidth-limited and multiple threads provide higher memory bandwidth.  This will almost certainly be limited to inputs that do not fit in the last level of cache. I've included a simple example program on how to do this.  This implementation uses old and widely-available features.  It may be possible to use OpenMP 5.0 user-defined reductions but I doubt it this provides a noticeable benefit in performance and you'll likely find many implementations do not support this feature. Note that my example program does not time repeated tests nor do any statistics on the timings.  Thus, you should not consider it a highly scientific test.  However, it demonstrates a clear benefit on my dual-core laptop for an array of 100M doubles, as expected. $ make minloc && ./minloc 100000000
icc -O3 -qopenmp -std=c11 minloc.c -o minloc
MINLOC of 100000000 elements with 4 threads
OpenMP: dt=0.076681, gmin=0.000000, gloc=4022958
Sequential: dt=0.157333, gmin=0.000000, gloc=4022958
SUCCESS Relevant Excerpt // thread-private result
        double mymin = DBL_MAX;
        double myloc = SIZE_MAX;

        // bottleneck parallel part
        #pragma omp for
        for (size_t i=0; i<n; ++i) {
            if (v[i] < mymin) {
                mymin = v[i];
                myloc = i;
            }
        }

        // write thread-private results to shared
        tmin[me] = mymin;
        tloc[me] = myloc;
        #pragma omp barrier

        // find global result
        #pragma omp master
        {
            for (int i=0; i<nt; ++i) {
                if (tmin[i] < gmin) {
                    gmin = tmin[i];
                    gloc = tloc[i];
                }
            }
        } Complete Example Program #include <stdio.h>
#include <stdlib.h>

#include <float.h>

#include <omp.h>

int main(int argc, char* argv[])
{
    size_t n = (argc > 1) ? atol(argv[1]) : 100;

    double * v = malloc(n * sizeof(double));
    if (v==NULL) abort();

    // g = global
    double gmin = DBL_MAX;
    size_t gloc = SIZE_MAX;

    const int mt = omp_get_max_threads();

    printf("MINLOC of %zu elements with %d threads\n", n, mt);

    // t = thread
    double * tmin = malloc(mt * sizeof(double));
    size_t * tloc = malloc(mt * sizeof(size_t));
    if (tmin==NULL || tloc==NULL) abort();

    for (int i=0; i<mt; ++i) {
        tmin[i] = DBL_MAX;
        tloc[i] = SIZE_MAX;
    }

    double dt = 0.0;

    #pragma omp parallel firstprivate(n) shared(v, tmin, tloc, gmin, gloc, dt)
    {
        const int me = omp_get_thread_num();
        const int nt = omp_get_num_threads();

        unsigned int seed = (unsigned int)me;
        srand(seed);
        #pragma omp for
        for (size_t i=0; i<n; ++i) {
            // this is not a _good_ random number generator, but it does not matter for this use case
            double r = (double)rand_r(&seed) / (double)RAND_MAX;
            v[i] = r;
        }

        double t0 = 0.0;

        #pragma omp barrier
        #pragma omp master
        {
            t0 = omp_get_wtime();
        }

        // thread-private result
        double mymin = DBL_MAX;
        double myloc = SIZE_MAX;

        // bottleneck parallel part
        #pragma omp for
        for (size_t i=0; i<n; ++i) {
            if (v[i] < mymin) {
                mymin = v[i];
                myloc = i;
            }
        }

        // write thread-private results to shared
        tmin[me] = mymin;
        tloc[me] = myloc;
        #pragma omp barrier

        // find global result
        #pragma omp master
        {
            for (int i=0; i<nt; ++i) {
                if (tmin[i] < gmin) {
                    gmin = tmin[i];
                    gloc = tloc[i];
                }
            }
        }

        #pragma omp barrier
        #pragma omp master
        {
            double t1 = omp_get_wtime();
            dt = t1 - t0;
        }

#if 0
        #pragma omp critical
        {
            printf("%d: mymin=%f, myloc=%zu\n", me, mymin, myloc);
            fflush(stdout);
        }
#endif
    }

    printf("OpenMP: dt=%f, gmin=%f, gloc=%zu\n", dt, gmin, gloc);
    fflush(stdout);

    // sequential reference timing
    {
        double t0 = omp_get_wtime();

        double mymin = DBL_MAX;
        double myloc = SIZE_MAX;

        for (size_t i=0; i<n; ++i) {
            if (v[i] < mymin) {
                mymin = v[i];
                myloc = i;
            }
        }

        gmin = mymin;
        gloc = myloc;

        double t1 = omp_get_wtime();
        dt = t1 - t0;
    }

    printf("Sequential: dt=%f, gmin=%f, gloc=%zu\n", dt, gmin, gloc);
    fflush(stdout);

    // debug printing for toy inputs
    if (n<100) {
        for (size_t i=0; i<n; ++i) {
            printf("v[%zu]=%f\n", i , v[i]);
        }
        fflush(stdout);
    }

    free(v);

    printf("SUCCESS\n");

    return 0;
}

A: You should first use the depend(in: ...) and depend(out: ...) to specify the input and output dependencies of the task.
Additionally, you must include the 3 conditionals into the task body as they read the cells of arrB written by the tasks.
Finally, you should add a #pragma omp parallel section and let only one thread create the tasks with either #pragma omp master of #pragma omp single . Here is a solution: printf("Array B:\n");
    #pragma omp parallel
    #pragma omp master
    for( i=0;i<3;i++){
        for( j=0;j<3;j++) {
            #pragma omp task \
                    firstprivate(i, j) \
                    private(diag, top, left) \
                    shared(arrA, arrB) \
                    depend(in: arrB[i-1][j], arrB[i][j-1]) \
                    depend(out: arrB[i][j])
            {
                diag = 0; top=0; left=0;
                if(i-1>=0 && j-1>=0) {
                    diag = arrB[i-1][j-1];
                }
                if(i-1>=0) {
                    top = arrB[i-1][j];
                }
                if(j-1>=0) {
                    left = arrB[i][j-1];
                }
                arrB[i][j] = diag + arrA[i][j] + (top-diag) + (left-diag);
            }
        }
    }
    #pragma omp taskwait Please note that the dependency arrB[i-1][j-1] is not specified as it is already included in the other indirectly. arrA[i][j] is not needed either since there are no other task writing into it. Both are optimizations. While this solution is correct, it will probably be run the code in sequential. The problem comes from the dependencies: OpenMP does not provide a simple way to add conditions for the first line and the first column. One way to overcome that is to split the code in 3 parts computing each possible case (cumbersome as it duplicate the code). Another way is to create the task in a different order so that false dependencies does not occur (eg. diagonal walk). Yet another way is to build yourself the dependencies with pointers (requires a good understanding of OpenMP). None of the solution is really good. PS: I guess that you want to play with OpenMP tasks and you do not expect any speed-up related to parallelizing this code as the computation is not enough intensive so that can be useful).

