#include <stdio.h>

int main(int argc, char **argv) {

    const int n=128;

    long x[n];
    long y[n];

    for (int i=0; i<n/2; i++) {
        x[i] = y[i] = 1;
        x[i+n/2] = 2;
        y[i+n/2] = 2;
    }

    #pragma omp simd
    for (int i=0; i<n; i++)
        x[i] = (x[i] == y[i]);

    for (int i=0; i<n; i++)
        printf("%d: %ld\n", i, x[i]);

    return 0;
}

