A: While this may not fix the runtime error you're seeing, I've updated your code so it will parallelize the loops.  You need to add "independent" to the "kernels" region to tell the compiler to ignore the dependencies.  Due to C allowing pointers of the same type to alias the same data, the compiler must assume that they do.  Hence, it can't automatically parallelize the loops. Also as written, "d_min_idx" will likely give a incorrect result.  Unfortunately you can both find the min value and it's index in the same parallel loop.  Hence it needs to be split into two loops.  I have it set to find the first index that matches the min value in the even multiple indices have the same value. #include <math.h>

void function1(double const *x, double *const *W, double *D, int num_out, int num_features, double alpha, int R)
{
    int j, k;

#pragma acc kernels loop independent
    for (j = 0; j < num_out; j++)
    {
        double sum = 0;
#pragma acc loop reduction(+:sum)
        for (k = 0; k < num_features; k++)
            sum += (W[j][k] - x[k]) * (W[j][k] - x[k]);
        D[j] = sum;
    }

    double d_min = INFINITY;
    int d_min_idx = -1;

#pragma acc parallel loop reduction(min : d_min)
    for (j = 0; j < num_out; j++)
    {
        if (D[j] < d_min)
        {
            d_min = D[j];
        }
    }
#pragma acc parallel loop reduction(min : d_min_idx)
    for (j = 0; j < num_out; j++)
    {
        if (D[j] == d_min)
        {
            d_min_idx = j;
        }
    }

    int from_node = max(0, d_min_idx - R);
    int to_node = min(num_out, d_min_idx + R + 1);

#pragma acc kernels loop collapse(2) independent
    for (j = from_node; j < to_node; j++)
    {
        for (k = 0; k < num_features; k++)
            W[j][k] += alpha * (x[k] - W[j][k]);
    }
} Compiler feedback messages: % nvc -c -w -acc -Minfo=accel test.c
