A: You can certainly do something like this with OpenMP, but it isn't as simple as putting #pragma omp parallel around a for loop.  For that structure, the compiler needs to know at the time of entering the loop how many iterations will be made, so that it can decompose the iterations across threads; and you necessarily don't have that information here when you're exiting once you've found something. You can make something like this work  - and it can be very useful if the test you need to perform is very CPU heavy (here, I have a made-up example of brute-force primality testing), so that you're breaking up the work amongst several cores, and you only care about finding a result (or that there are none).  But note that you are definitely not guaranteed that doing this in parallel will return the first result. In the below example, we have a flag found that is set (using an omp atomic capture construct) when a thread finds an item.  If it was the first to set the flag, it stores the value and location.  Once the threads (eventually) see the flag has been set, they all return from the while loop. #include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include "omp.h"

/* brute force prime-testing algorithm */
int isprime(int x) {
    int prime = 1;
    for (int i=2; i<=floor(sqrt(1.0*x)); i++) {
        if (x % i == 0) {
            prime = 0;
            break;
        }
    }
    return prime;
}

int main(int argc, char **argv) {

    const int MAXN=128;
    int start=200;
    if (argc > 1)
        start = atoi(argv[1]);

    int candidates[MAXN];
    for (int i=0; i<MAXN; i++) {
        candidates[i] = start+i;
    }

    int found=0;
    int value=-1;
    int location=-1;
#pragma omp parallel shared(found, candidates, value, location) default(none)
    {
        int tid=omp_get_thread_num();
        int nthreads=omp_get_num_threads();
        int item=tid;

        while (!found && item < MAXN) {
            int prime=isprime(candidates[item]);
            if (prime) {
                int alreadyfound=0;
#pragma omp atomic capture 
                { alreadyfound = found; found++; }
                if (!alreadyfound) {
                    location = item;
                    value = candidates[item];
                }
            }
            item += nthreads;
        }
    }

    if (!found)
        printf("No primes found\n");
    else 
        printf("Found prime: %d (%d) in location %d (%d)\n", value, isprime(value), location, candidates[location]);

    return 0;
} Running gives $ gcc -o stopwhenfound stopwhenfound.c  -std=c99 -lm -fopenmp
