A: setting the number of threads num_threads manually is usually wrong in computational code, as setting them lower or higher than your actual number of cores will penalize your performance, as threads will be contesting on the available cores or underutilizing them. instead you should rely on #pragma omp parallel for to distribute work to the correct number of threads (the total number of threads of your processor). #pragma omp parallel for schedule(dynamic)
for (int y = 0; y < height; y++)
{
...
} the parallel version is now about twice as fast as the single-thread version. you may want to play with the blocks in schedule(dynamic, blocks) to get the best number of chunks per core, but because the work is very small , twice as fast is the best you can get. MWE with const correctness #include <opencv2/opencv.hpp>
#include <iostream>
#include <omp.h>

void cpu_PeakFinder(const cv::Mat& img, cv::Mat& peak);
void cpuMp_PeakFinder(const cv::Mat& img, cv::Mat& peak);

int main()
{
    cv::Mat img(64, 5120, CV_8UC1);
    /*==========================================================================
    ============================================================================\*/

    {
        cv::Mat peak_cpu(img.rows, img.cols, CV_8UC1, cv::Scalar(0));

        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
        for (int k = 0; k < 11000; k++)
            cpu_PeakFinder(img, peak_cpu);

        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
        std::cout << "Time difference = " << std::chrono::duration_cast<std::chrono::milliseconds>(end - begin).count() << "[ms]" << std::endl;
        // cv::transpose(peak_cpu, peak_cpu);
        // imshow("peak_cpu", peak_cpu);
    }
    /*==========================================================================
    ============================================================================*/
    {
        cv::Mat peak_mp(img.rows, img.cols, CV_8UC1, cv::Scalar(0));
        uchar *ppeakMp = peak_mp.data;

        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
        for (int k = 0; k < 11000; k++)
            cpuMp_PeakFinder(img, peak_mp);

        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
        std::cout << "Time difference parallel = " << std::chrono::duration_cast<std::chrono::milliseconds>(end - begin).count() << "[ms]" << std::endl;
        // transpose(peak_mp, peak_mp);
        // imshow("peak_mp", peak_mp);
    }

    // cv::waitKey();
    return 0;
}

void cpu_PeakFinder(const cv::Mat& img, cv::Mat& peak)
{
    uchar *pimg = img.data;
    uchar *ppeak = peak.data;
    int height = img.rows;
    int width = img.cols;
    int offset, x, y, row;
    int max, idx;
    for (y = 0; y < height; ++y)
    {
        max = pimg[width * y + 0];
        idx = 0;
        for (x = 0; x < width; ++x)
        {
            offset = width * y + x;
            if (max < pimg[offset])
            {
                max = pimg[offset];
                idx = offset;
            }
        }
        ppeak[idx] = 255;
    }
}

void cpuMp_PeakFinder(const cv::Mat& img, cv::Mat& peak)
{
    uchar *pimg = img.data;
    uchar *ppeakMp = peak.data;
    const int width = img.cols;
    const int height = img.rows;
    int offset, x, y;
    int max, idx;

    #pragma omp parallel for schedule(dynamic)
    for (int y = 0; y < height; y++)
    {
        max = pimg[width * y + 0];
        idx = 0;

        for (x = 0; x < width; ++x)
        {
            offset = width * y + x;
            if (max < pimg[offset])
            {
                max = pimg[offset];
                idx = offset;
            }
        }
        ppeakMp[idx] = 255;
    }
}

