 #pragma omp parallel for num_threads(3) firstprivate(i)
 for(n=0; n<10; ++n)
 {
        tid = gettid();
        pt = pthread_self();
        printf("i=%d -  %d - thread : %d :: TID=%d\n",i++, n, omp_get_thread_num(), gettid());
 }
printf("TID : %d - PT=%d\n", tid, pt);
pthread_cancel(pt);
