A: Since the outer for can't be parallelized due to the constant changes in the array, we need to parallelize the inner for. So we need to use the max reduction, but since we just don't need the maximum value we also need the index of this maximum value, we need to declare a new reduction (Only available in OpenMP 4.0) that receives a struct, here it is fully functional: #include <stdio.h>
#include <omp.h>

struct Compare { int val; int index; };
#pragma omp declare reduction(maximum : struct Compare : omp_out = omp_in.val > omp_out.val ? omp_in : omp_out)

void selectionsort(int* arr, int size)
{
    for (int i = size - 1; i > 0; --i)
    {
        struct Compare max;
        max.val = arr[i];
        max.index = i;
        #pragma omp parallel for reduction(maximum:max)
        for (int j = i - 1; j >= 0; --j)
        {
            if (arr[j] > max.val)
            {
                max.val = arr[j];
                max.index = j;
            }
        }
        int tmp = arr[i];
        arr[i] = max.val;
        arr[max.index] = tmp;
    }
}

int main()
{
        int x[10] = {8,7,9,1,2,5,4,3,0,6};
        selectionsort(x, 10);

        for (int i = 0; i < 10; i++)
                printf("%d\n", x[i]);
        return 0;
}
A: The solution posted by Gabriel Garcia works only for arrays of natural numbers . If you use this array you get a wrong result: int x[10] = {-8,-7,-9,-1,-2,-5,-4,-3,0,-6}; The reduction declaration: #pragma omp declare reduction(maximum : struct Compare : omp_out = omp_in.val > omp_out.val ? omp_in : omp_out) does not specify an initializer-clause and therefore at every iteration of the parallel loop the max.val and max.index are initialized to 0 even though we initialize them before the loop. Refer to user defined reduction syntax for more information. The correct declaration should be: #pragma omp declare reduction(maximum : \
                              struct Compare : \
                              omp_out = omp_in.val > omp_out.val ? omp_in : omp_out) \
                              initializer(omp_priv=omp_orig) You can also do a 'minimum' reduction in the same way if you prefer (obviously, changing the indexes and relationship symbols).

A: Parallel.For provides several overloads that allow one to store per-thread state variables. One of them is (fully described here ): public static ParallelLoopResult For<TLocal>(
    int fromInclusive,
    int toExclusive,
    Func<TLocal> localInit,
    Func<int, ParallelLoopState, TLocal, TLocal> body,
    Action<TLocal> localFinally
) TLocal could be any type, e.g. float[] in your case, and the localInit() function is called once per thread to initialise an instance of that type in the local storage of the thread, which instance then gets passed to the body. The body function should then return the state and it will be passed to the next iteration and so on. Your code should look something like this: Parallel.For<float[]>(0, 500,
   () => new float[1000],
   (i, loop, data) =>
   {
      for(int j = 0; j < 1000; j++)
      {
         data[j] = 100;
         // do some computation using data
      }
      return data;
   },
   (data) => {}
); Microsoft provides an example of doing this here .

