A: You can roll-your-own concurrent vector as well  as min and max reductions by filling private versions of the variables in parallel and then merging them in a critical section.  This will work in MSVC which only supports OpenMP 2.5 (which does not support min and max reductions).  But irrespective of whether your version of OpenMP supports min and max reductions this is a useful technique to learn. This method is efficient as long as the number of items you loop over is much larger than the number of threads (or the time run over the items is large compared to the merging). #pragma parallel 
{
    int m_lmin_private = m_lmin;
    int m_max_private = m_max_private;
    #pragma omp for nowait
    for (size_t i = 0; i < m_patterns.size(); ++i) {
        if (m_patterns[i].size() < m_lmin_private)          
            m_lmin_private = m_patterns[i].size();          
        else if (m_patterns[i].size() > m_lmax_private)           
            m_lmax_private = m_patterns[i].size();
    }
    #pragma omp critical
    {
        if (m_lmin_private<m_lmin)          
            m_lmin = m_lmin_private;    
        if (m_lmax_private>m_lmax)           
            m_lmax = m_lmax_private;                     
    }
} For concurrent vectors us the same method: std::vector<int> vec;
#pragma omp parallel
{
    std::vector<int> vec_private;
    #pragma omp for nowait //fill vec_private in parallel
    for(int i=0; i<n; i++) {
        vec_private.push_back(i);
    }
    #pragma omp critical
    vec.insert(vec.end(), vec_private.begin(), vec_private.end());
}
