                  int na)
{
    const Eigen::Index szZ = DPC.rows();
    const Eigen::Index szX = DPC.cols();
    Eigen::MatrixXd DPCint(szZ * na, szX);
    const auto avals = Eigen::VectorXd::LinSpaced(na, 0., (na - 1) * 0.25);
    const auto xvals = Eigen::VectorXd::LinSpaced(szX, 0., (szX - 1) * 1.34);
    const Eigen::VectorXd zvals =
          Eigen::VectorXd::LinSpaced(szZ, 0., (szZ - 1) * 12.68);
#   pragma omp parallel
    {
#       pragma omp for collapse(2)
        for(Eigen::Index a = 0; a < na; ++a)
            for(Eigen::Index x = 0; x < szX; ++x)
                DPCint.col(x).segment(a * szZ, szZ) =
                      zvals.array() + xvals[x] + avals[a];

#       pragma omp for nowait
        for(Eigen::Index x = 0; x < szX; ++x)
            for(Eigen::Index a = 0; a < na; ++a)
                DPC.col(x) += DPCint.col(x).segment(a * szZ, szZ);
    }
} 13.3 seconds. Note that on my laptop (Intel i7-8850H), this was significantly faster than the rowwise version. NUMA and cache line bouncing may be a serious issue on the larger threadripper but I didn't investigate perf counters. Reordering DPCint At this point I think it becomes apparent that the layout of the DPCint and the loop ordering in its setup are a liability. Maybe there is a reason for it. But if there isn't, I propose changing it as follows: void reordered(Eigen::Ref<Eigen::MatrixXd> DPC,
               int na)
{
    const Eigen::Index szZ = DPC.rows();
    const Eigen::Index szX = DPC.cols();
    Eigen::MatrixXd DPCint(szZ * na, szX);
    const Eigen::VectorXd avals =
          Eigen::VectorXd::LinSpaced(na, 0., (na - 1) * 0.25);
    const auto xvals = Eigen::VectorXd::LinSpaced(szX, 0., (szX - 1) * 1.34);
    const auto zvals = Eigen::VectorXd::LinSpaced(szZ, 0., (szZ - 1) * 12.68);
#   pragma omp parallel
    {
#       pragma omp for
        for(Eigen::Index x = 0; x < szX; ++x)
            for(Eigen::Index z = 0; z < szZ; ++z)
                DPCint.col(x).segment(z * na, na) =
                      avals.array() + xvals[x] + zvals[z];

#       pragma omp for nowait
        for(Eigen::Index x = 0; x < szX; ++x)
            DPC.col(x) += DPCint.col(x).reshaped(na, szZ).colwise().sum();
    }
} The idea is to reshape it in such a way that a) colwise sums are possible and b) The same thread touches the same elements in the first and second loop. Interestingly, this seems slower at 15.3 seconds. I guess the innermost assignment is now too short. What happens if we fold both parts of the algorithm into one loop, reducing the synchronization overhead and improving caching? void reordered_folded(Eigen::Ref<Eigen::MatrixXd> DPC,
                        int na)
{
    const Eigen::Index szZ = DPC.rows();
    const Eigen::Index szX = DPC.cols();
    Eigen::MatrixXd DPCint(szZ * na, szX);
    const Eigen::VectorXd avals =
          Eigen::VectorXd::LinSpaced(na, 0., (na - 1) * 0.25);
    const auto xvals = Eigen::VectorXd::LinSpaced(szX, 0., (szX - 1) * 1.34);
    const auto zvals = Eigen::VectorXd::LinSpaced(szZ, 0., (szZ - 1) * 12.68);
#   pragma omp parallel for
    for(Eigen::Index x = 0; x < szX; ++x) {
        for(Eigen::Index z = 0; z < szZ; ++z)
            DPCint.col(x).segment(z * na, na) =
                  avals.array() + xvals[x] + zvals[z];
        DPC.col(x) += DPCint.col(x).reshaped(na, szZ).colwise().sum();
    }
} 12.3 seconds. At this point, why do we even have a shared DPCint array? Let's use a per-thread matrix. void reordered_loctmp(Eigen::Ref<Eigen::MatrixXd> DPC,
                      int na)
{
    const Eigen::Index szZ = DPC.rows();
    const Eigen::Index szX = DPC.cols();
    const Eigen::VectorXd avals =
        Eigen::VectorXd::LinSpaced(na, 0., (na - 1) * 0.25);
    const auto xvals = Eigen::VectorXd::LinSpaced(szX, 0., (szX - 1) * 1.34);
    const auto zvals = Eigen::VectorXd::LinSpaced(szZ, 0., (szZ - 1) * 12.68);
#   pragma omp parallel
    {
        Eigen::MatrixXd DPCint(na, szZ);
#       pragma omp for nowait
        for(Eigen::Index x = 0; x < szX; ++x) {
            for(Eigen::Index z = 0; z < szZ; ++z)
                DPCint.col(z) = avals.array() + xvals[x] + zvals[z];
            DPC.col(x) += DPCint.colwise().sum();
        }
    }
} Heureka! 6.8 seconds. We eliminated cache-line bounding. We made everything cache-friendly and properly vectorized. The only thing I can think of now is turning DPCint into an expression that is evaluated on the fly but this very much depends on the actual expression. Since I cannot speculate on that, I'll leave it at that.

A: The problem comes from collapse(2) clause and is also related to the code auto-vectorization . Indeed, both compilers are not able to auto-vectorize the loop with the collapse, but ICC use a very expensive idiv instruction in the middle of the hot loop (which is very bad) while GCC produce a better code. This comes from the collapse(2) clause which is not well optimized (on many compilers). You can see that on Godbolt . Note that optimizing a kernel using a collapse(2) clause is not easy since the compiler do not know the bound of the loops and so the associated cost (as well as the divider for the modulus). Without the collapse(2) , GCC is able to vectorize the loop successfully but surprisingly not ICC. Fortunately, we can help ICC using the simd directive . Once used, the two compilers generate a relatively good code. It is still not optimal because size_t is generally 8 bytes and int is 4 bytes on mainstream x86-64 platforms and the loop comparison of the different types makes the code harder to vectorize efficiently as well as to produce the best scalar instructions. You can use a temporary variable to fix that. You can see the resulting  assembly code here . Note that the assembly generated by ICC is very good once the code is fixed. The code is memory bound and the final code should saturate the RAM with only few threads. Even the L3 cache should be saturated with the ICC produced assembly if the input array would fit into it. Here is the fixed code: for(int k = 0; k < bench_rounds; ++k) {
    int limit = large_vec_size;
    #pragma omp parallel for
    for(int j = 0; j < limit; ++j) {
        #pragma omp simd
        for(int i = 0; i < limit; ++i) {
           test_vec[j * large_vec_size + i] = i + j + test_vec[j * large_vec_size + i] * 1e-13;
        }
    }
} Moreover, not that the result is not used and optimizing compilers can just remove the benchmark code because it does not actually have any side effects (dead-code elimination). Generally, you can fix that by just printing the result. This is also useful to check the results .

A: You have some typos on the OpenMP constructors, namely: #pragma omp parallal -> #pragma omp parallel; #pragma omp parallel for -> #pragma omp for Regarding 2. you do not need the parallel because you are already inside a parallel region. Try the following: using namespace std;

int main(){

        int totalSum = 0, ompSum = 0;
        const int N = 1000;
        int array[N];
        for (int i=0; i<N; i++){
                array[i]=i;
        }
        #pragma omp target
        {
                #pragma omp parallel private(ompSum) shared(totalSum)
                {
                        ompSum=0;
                        #pragma omp for
                        for (int i=0; i<N; i++){
                                ompSum += array[i];
                        }

                        #pragma omp critical
                        totalSum += ompSum;
                }


                printf ( "Caculated sum should be %d but is %d\n", N*(N-1)/2, totalSum );
        }

        return 0;
}

A: This code: #pragma omp parallel for shared(cnt, offset) private(i)
for (i = 0; i < n; ++i) {
  ++cnt[offset[i]];
} contains a race-condition during the updates of the array cnt , to solve it you need to guarantee mutual exclusion of those updates. That can be achieved with (for instance) #pragma omp atomic update but as already pointed out in the comments: However, this resolves just correctness and may be terribly
inefficient due to heavy cache contention and synchronization needs
(including false sharing). The only solution then is to have each
thread its private copy of cnt and reduce these copies at the end. The alternative solution is to have a private array per thread, and at end of the parallel region you perform the manual reduction of all those arrays into one. An example of such approach can be found here . Fortunately, with OpenMP 4.5 you can reduce arrays using a dedicate pragma, namely: #pragma omp parallel for reduction(+:cnt) You can have look at this example on how to apply that feature. Worth mentioning that regarding the reduction of arrays versus the atomic approach as kindly point out by @Jérôme Richard : Note that this is fast only if the array is not huge (the atomic based
solution could be faster in this specific case regarding the platform
and if the values are not conflicting). So that is m << n. – As always profiling is the key!; Hence, you should test your code with aforementioned approaches to find out which one is the most efficient.

A: TL:DR: use Word unchanged = -1ULL; and update it with unchanged &= (old == lhs[i]) ? -1ULL : 0; so this maps naturally to a SIMD compare-for-equal and SIMD AND. Or even better, changed |= old ^ lhs[i]; vectorizes nicely with GCC and clang, for Word changed = 0; .  With clang, it gives optimal asm.  With GCC, the first way is better because GCC pessimizes to changed |= (~old) & rhs[i];  // find RHS bits that weren't already set costing an extra movdqa register copy, or with AVX removing the ability to fold the unaligned load into a memory source for vpor (because it needs both operands twice, once for this and once for the main | ). Compare-for-unequal isn't directly available until AVX-512; doing that would have to invert the compare result before combining into a changed vector. The overall operation can be vectorized manually with intrinsics (or asm) pretty much as written, without any major transformations, except of course optimizing to bitwise | OR instead of actual short-circuit evaluation.  So this is basically a missed optimization. But in the natural asm implementation of this, your vector of changed elements would be the same width as the data, not just 4 bool s. (For x86 that would take an extra vmovmskpd to feed a scalar or instead of just a SIMD vpor , and most ISAs don't have a movemask operation so maybe the generic vectorizer isn't even considering using it.  Fun fact: clang auto-vectorizes your original code really badly, doing a horizontal OR down to a scalar bool every iteration.) Using Word changed = 0; lets this vectorize fairly decently , with changed |= ... , with or without OpenMP pragmas (differently, haven't sorted out which is actually better for every combo).  Compilers are dumb (complex pieces of machinery, not human understanding) and often don't figure out things like this for themselves - auto-vectorization is hard enough that they sometimes need some hand-holding. So the trick is making changed the same width as the array elements. If you use OpenMP, you need to tell the OpenMP vectorizer about reductions such as sum of an array with + , or in this case OR.  In this case, #pragma omp simd reduction(|:changed) .  You should be using changed |= stuff instead of logical short-circuit eval anyway, if you want this to vectorize into branchless SIMD. reduction(|:changed) actually seems to override your actual code to some degree, so be careful it matches. ICC even breaks your code (not updating changed in the SIMD part) if you just use #pragma omp simd https://godbolt.org/z/bG98Kz . (Perhaps that gives it license to ignore serial dependencies, or at least reductions, which you didn't tell it about?  Either that or an ICC bug, I don't know OpenMP very well.) With the original bool changed instead of Word , GCC doesn't auto-vectorize at all, and clang does a nasty job (horizontal reduction to a scalar bool inside the inner loop!) Two versions that auto-vectorize: On Godbolt with -O3 -march=nehalem -mtune=skylake -fopenmp (So using SSE4.1 / 4.2, but not AVX or BMI1/BMI2).  I haven't looked in detail at which ends up with less clunky cleanup code. #include <stddef.h>
typedef unsigned long long Word;

bool fun_v1(Word *lhs, const Word *rhs, size_t s)
{
    Word changed = 0;
    #pragma omp simd reduction(|:changed)  // optional, some asm differences with/without
    for (size_t i = 0; i < s; ++i) {
        const Word old = lhs[i];
        changed |= (~old) & rhs[i];   // find RHS bits that weren't already set. pure bitwise, no 64-bit-element SIMD == needed.  Do this before storing so compiler doesn't have to worry about lhs/rhs overlap.
        lhs[i] |= rhs[i];
        //changed |= (old != lhs[i]) ? -1ULL : 0;    // requires inverting the cmpeq result, but can fold a memory operand with AVX unlike the bitwise version

        //changed = changed || (old != lhs[i]);    // short circuit eval is weird for SIMD, compiles inefficiently.
    }

    return changed;
} ( update: changed |= old ^ lhs[i]; appears even better to get a non-zero value on not-equal.  It uses only commutative operations, and doesn't need == / pcmpeqq.  @chtz suggested this in comments, I haven't rewritten the rest of the answer to cut out discussion of worse optoins.   clang will auto-vectorize with it, and with AVX allows a memory source operand for rhs because it's only needed once. https://godbolt.org/z/ex5519 . So this appears to be the best of both worlds.) changed |= (old != lhs[i]) ? -1ULL : 0; is also still only 10 instructions (9 uops) in the inner loop, same as changed |= (~old) & rhs[i]; , for GCC 10.2 without AVX.  But for clang, that defeats auto-vectorization!  Clang will handle changed |= (old != lhs[i]); (or with an explicit ? 1 : 0 ) so that's odd. -1ULL avoids needing a set1_epi64x(1) vector constant so I used that. Versions using == or != will need SSE4.1 pcmpeqq for vectorization of 64-bit compare for == :  compilers probably aren't going to be smart enough to realize that any integer element-size is fine for the overall thing.  And emulating a narrower compare probably won't look profitable. The ~old & rhs[i] way works with just SSE2.  Ending the loop with SSE4.1 ptest instead of shuffles and POR and MOVQ would be more efficient, but compilers are pretty dumb about stuff like that.  (And handling the ends of loops in general.
Just naive reduction, and scalar cleanup for odd elements instead of a possibly-overlapping final vector that ends at the end of the arrays. |= is idempotent so at worst it would cause a store-forwarding stall if you don't schedule your loads well.  That's another thing you could do better with manual vectorization, but using intrinsics would force one SIMD vector width, while auto-vec lets the compiler use wider vectors when you compile for an AVX2 CPU like -march=haswell or -march=znver2 .) Until AVX-512, only compare for == is available (or > ), not != directly.  To reduce that the way we want, we'd need to unchanged &= (old == updated); .  This lets GCC save 1 instruction in the loop, bringing it down to 9 instructions, 8 uops.  It can possibly run at 1 iteration per 2 cycles. But clang for some reason doesn't auto-vectorize it at all.  Apparently clang doesn't like the ? -1 : 0 ternary here or in the other version, maybe not realizing that's what SIMD compares produce. bool fun_v2(Word *lhs, const Word *rhs, size_t s)
{
    Word unchanged = -1ULL;
// clang fails to vectorize?!?  GCC works as expected with/without pragma
    #pragma omp simd reduction(&:unchanged)
    for (size_t i = 0; i < s; ++i) {
        const Word old = lhs[i];
        lhs[i] |= rhs[i];
        unchanged &= (old == lhs[i]) ? -1ULL : 0;
    }
    return !unchanged;
} With AVX available, vpor with a memory source operand would be efficient if compilers weren't using a stupid indexed addressing mode, forcing it to un-laminate on Intel Sandybridge family (but not on AMD). Note that if you're thinking of using Word as a wide type to use this on arbitrary data of other types, beware strict-aliasing rules and Undefined Behaviour .  Manual vectorization might be a good bet because _mm_loadu_si128((const __m128*)int_ptr); is fully strict-aliasing safe: vector pointers (and load / store intrinsics) are like char* in that they can alias anything.  For a portable version, either use memcpy or GNU C typedef unsigned long unaligned_aliasing_chunk __attribute__((may_alias,aligned(1))) .  "Word" has different meanings in asm for different ISAs, like being 16-bit in x86, so it's not the best name for a type you want to be was wide as the machine can efficiently use. unsigned long is often that, but is 32-bit on some 64-bit machines. unsigned long long is probably fine.

A: Not easily. SIMD works quite well when you have values in the next N steps that behave the same way. So consider for example an array of 2D vectors: X Y X Y X Y X Y If we were to do a vector addition operation here, X Y X Y X Y X Y
+ + + + + + + +
X Y X Y X Y X Y The compiler will nicely vectorise that operation. If however we were to want to do something different for the X and Y values, the memory layout becomes problematic for SIMD: X Y X Y X Y X Y
+ / + / + / + /
X Y X Y X Y X Y If you consider for example the multiplication case: (a + bi) (c + di) = (ac - bd)  (ad + bc)i Suddenly the operations are jumping between SIMD lanes, which is pretty much going to kill any decent vectorization. Take a quick look at this godbolt: https://godbolt.org/z/rnVVgl Addition boils down to some vaddps instructions (working on 8 floats at a time). 
Multiply ends up using vfmadd231ss and vmulss (which both work on 1 float at a time). The only easy way to automatically vectorise your complex code would be to seperate out the real and imaginary parts into 2 arrays: struct ComplexArray {
  float* real;
  float* imaginary;
}; Within this godbolt you can see that the compiler is now using vfmadd213ps instructions (so again back to working on 8 floats at a time). https://godbolt.org/z/Ostaax

A: According to the OpenMP standard 4.5 , you cannot reduce a variable that is used in the task constructor. A list item that appears in a reduction clause of the innermost
  enclosing worksharing or parallel construct may not be accessed in an
  explicit task. Nevertheless, it looks like that feature will be covered by OpenMP 5.0. Looking at your code the better approach is actually to use the parallel for with the reduction clause, anyway.
A: dreamcrash's answer is spot on. OpenMP 5.0 has added task reduction support, but OpenMP 5.0 is not widely supported yet, afaik only the Intel compiler supports a preview of OpenMP 5.0 that includes task reduction. If you really must use reduction with tasks with OpenMP previous to 5.0, you can basically declare the reduction variable as threadprivate and do a manual reduction as outlined in this talk . It would look something like this: int sum = 0;
int thread_sum = 0;
#pragma omp threadprivate(sum)
#pragma omp parallel
{
    #pragma omp single
    for(int i=0; i<10; i++)
    {
        #pragma omp task
        {
            printf("Thread: %d\n", omp_get_thread_num());
            int y = 5;
            thread_sum += y;
        }
    }
    #pragma omp atomic
    sum += thread_sum
}

A: This scenario is typically employed by task parallelism , where first, you need to create a fixed number of threads and second, you define some tasks that are then distributed to these threads by OpenMP runtime. Definition of tasks (via #pragma omp task or #pragma omp section ) must be done within a parallel section. However, there are situations, such as within quicksort, where it does not make sense to define tasks from multiple threads; to define them from a single thread only, you use #pragma omp single . Parallelization of quicksort is not trivial. Additionally to tasking, you also need to execute partitioning in parallel at the top levels of recursion. This is in OpenMP achieved via nested parallelism . Consider, e.g., quicksort and 8 cores: You create 8 threads ( #pragma omp parallel ). You invoke quicksort by a single thread only ( #pragma omp single ). Within quicksort , you invoke partition , which splits the single threads into 8 threads via nested parallelism and performs partitioning in parallel. Finally, 2 partitions are created. The single thread now creates 2 tasks ( #pragma omp task ) and invoke itself recursively within them by invoking quicksort . OpenMP runtime assigns these 2 tasks to any of 8 available threads, since all are idle now. Now, 2 threads are executing the quicksort function. This case only describes the top level of recursion. At lower levels, you need to care about load balancing , since both partitions may be of different sizes. (On the 2nd level, there are two threads executing partition concurrently. However, due to generally different sizes of both partitions, you, e.g., split the 1st thread into 3 threads and the 2nd thread into 5 threads to utilize all 8 cores. Basically you want all these cores to be utilized as much as possible, which is quite a challenge for multithreaded quicksort developers.) Efficient implementation will also employ tail call optimization , where only 1 task will be created instead of 2; it saves a lot of stack space and avoid many call instructions. Below some threshold, you then switch to sequential quicksort (or rather to some combination of quicksort, insertion sort, and heapsort, for instance). For illustration, this is the trivial implementation of parallel quicksort with OpenMP for sorting an array of integers: void par_qs_rec(int* a, long lo, long hi) {
   if (lo < hi) {
      long p = partition(a, lo, hi);
      #pragma omp task
      par_qs_rec(a, lo, p - 1);
      #pragma omp task
      par_qs_rec(a, p + 1, hi);
   }
}

void par_qs(int* a, long lo, long hi) {
   #pragma omp parallel 
   {
      #pragma omp single
      par_qs_rec(a, lo, hi); // (1)
   }
} What would happen if there was no #pragma omp single , i.e., if initial par_qs_rec would be invoked by all threads at (1) ?

