A: This method is 5 times faster than the corrected OP. It first makes an array of primes up to the square root, single threaded. Then the multiple threads only read from that array. /* Prime numbers by trial division, with parallel 2nd step */
/* Trick is to make sure the SQR array has top prime > SQR to make the for loop work until the end / the last p[i]
   Lowest MAX is 4 */
/* Timing: 0.13s for up to 10M (4 cores, turbo boost 3GHz) */

/* single threaded, array filling step only: timing:
./a.out 1000000000000
top: 78497 1000003 1000006000009
-> 0.04s for 78K primes up to 1M, ready for 1T (would take hours/years) 
-> does not matter overall
*/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <omp.h>

/* Fill p[] with primes up to 'max', and one more */
int
primearray(int max, int p[]) {

    p[0] = 3;
    int top = 0, n, i;

    for (n = 5;; n += 2)
        for (i = 0;; i++)

            if (n % p[i] == 0)
                break;
            else
                if (p[i]*p[i] > n) {

                    p[++top] = n;
                    if (n > max)
                        return top;          // return WITH last n
                    break;
                }
}
/* Use primes in p[] to check up to 'max' */
/* "5" is p[1] is the 3rd prime, so start count from 2 */
int
primecount_omp(long max, int p[]) {

    int n, i, sum = 2;

    #pragma omp parallel for private(i) schedule(guided) reduction(+:sum)

    for (n = 5; n <= max; n += 2)
        for (i = 0;; i++)

            if (n % p[i] == 0)
                break;
            else
                if (p[i]*p[i] > n) {
                    sum++;
                    break;
                }
    return sum;
}
/* Call primearray() with SQR and then primecount_omp() with MAX */
/* PNT (x/logx) to find approx. size of array p[] 'psize'. Needs some safety margin. */
int
main(int argc, char** argv) {

    if (argc < 2) {
        printf("No limit given\n");
        return 1;
    }
    long MAX = strtoul(argv[1], 0, 10);
    int  SQR = sqrt(MAX);

    int   psize = 50 + 1.2 * SQR / log(SQR);
    int      *p = malloc(psize * sizeof*p);

    int top = primearray(SQR, p);

    printf("psize: %d top: %d %d %ld\n", psize, top, p[top], (long)p[top]*p[top]);

    int sum = primecount_omp(MAX, p);

    printf("Count: %d (%.2f%%)\n", sum, (double) 100*sum / MAX) ;
    double lnx = MAX / log(MAX);
    printf("LnX:   %.2f (%f)\n",  lnx, sum / lnx);

    return 0;
} The two functions are similar, but not identical. The first one has: p[++top] = n;
   if (n > max)
       return top;
   break; This is more complicated than the 2nd, parallel one: sum++;
   break; And while sum++ can be done with a reduction(+:sum) clause, the ++top would have to be coordinated between the threads. This is the fastest simple trial division method, I believe. It has an array, two steps and OMP, but still is simple. The output is: psize: 520 top: 445 3163 10004569
Count: 664579 (6.65%)
LnX:   620420.69 (1.071175) meaning 520 integers were allocated, 445 were used: 3163 is the largest prime needed, with a square above max of 10M. The exact (allocated) array sixe is not so important, just has to be big enough. A few thousand will get you very far. I like this because it does the recursive idea: To find the primes up to N, find first the primes up to SQRT(N) with only one "recursion" (formally w/o) and offering opportunity to easily parallelize the second, big step. If it is done in one step, then either you need an additional test or it continues to fill the array to the end. If it is done really recursively, you sqrt your way down to 3 or 2, and then use short arrays to make longer ones, all in the same way.
