    long gimmieTheFunc = gimmie_the_func();
    int marker = DIM-1; 
///    #pragma omp parallel for private(i, j, k, compute_it)
#   pragma omp parallel for private(i, j, k, compute_it) reduction(+:aggregate) 
                    /// introduced a reduction on aggregate
    for (i=1; i<marker; i++) {
