        std::vector<double> res;
        for (int i = 0; i < 10; ++i)
        res.push_back(i * i);
        // DANGER
        r.y = std::move(res);
    }
    #pragma omp single nowait
    {
        std::vector<double> res;
        for (int i = 0; i < 10; ++i)
        res.push_back(i * i + 2);
        // DANGER
        r.z = std::move(res);
    }
