A: Your code #pragma omp parallel for
    for(int i = 0; i < 5; i++)
    {
        cout << i << " " << omp_get_thread_num() << endl;
    } is equivalent to #pragma omp parallel for
    for(int i = 0; i < 5; i++)
    {
        cout << i;
        cout << " ";
        cout << omp_get_thread_num();
        cout << endl;
    } Calls to << in the different threads may be executed in any order. For instance cout << i; in thread 3 may be followed by cout << i; in tread 0 which may be followed by cout << " "; in thread 3 etc. resulting in the garbled output 30 ... . The correct way is to rewrite the code so that each thread calls cout << only once in the loop: #pragma omp parallel for
    for(int i = 0; i < 5; i++)
    {
        stringstream ss;
        ss << i << " " << omp_get_thread_num() << '\n';
        cout << ss.str();
    }
