A: A rudimentary way of doing this for a parallel region would be as follows: int total_threads = ...;
double time_taken_by_threads[total_threads];
#pragma omp parallel region num_threads(total_threads)
{
    int threadID = omp_get_thread_num();
    double start = omp_get_wtime();
     // parallel task
    double end = omp_get_wtime();
    time_taken_by_threads[threadID] = end - start;
}  
for(int i = 0; i < total_threads; i++)
   printf("Thread %d took, %ld (s)", time_taken_by_threads[i]; You create an array to store the time taken per thread. You use omp_get_wtime before and after the parallel task performed by the thread. Finally, you save the result in the array. And outside the parallel region you check the time that each thread has taken. This works fine with the parallel region but might not be so great for other OpenMP parallel constructors such as tasks for instead. The most robust solution is to use a profiler for OpenM for instance VTune .

A: TL;DR The first method does not have a race-condition whereas the second method has. The first method does not have a race-condition whereas the second method has. Namely, in the first method: #pragma omp parallel for shared(sum) num_threads(4)
for(i=0; i<NUM_STEP; i++)
    sum[i] = step*f(from+i*step);
for(i=0; i<NUM_STEP; i++)
    result += sum[i]; each thread saves the result of the operation step*f(from+i*step); in a different position of the array sum[i] . And after that the master thread, sequentially reduces the values saved on the array sum , namely: for(i=0; i<NUM_STEP; i++)
    result += sum[i]; Actually, there is a slight improvement that you can make on this version; instead of allocating the array sum with the same size as the number of NUM_STEP , you can just allocated it with the same size as the number of threads, and each thread would save in a position equals to its ID , namely: int total_threads = 4;
double sum[total_threads];
#pragma omp parallel num_threads(total_threads)
{
  int thread_id = omp_get_thread_num();
  for(i=0; i<NUM_STEP; i++)
      sum[thread_id] += step*f(from+i*step);
  for(i=0; i< total_threads; i++)
      result += sum[i];
} Nonetheless, the best approach will be to actually fix the second method. On the second method there is a race-condition on the update of the variable result : #pragma omp parallel for shared(result) num_threads(4)
for(i=0; i<NUM_STEP; i++)
    result += step*f(from+i*step); because the result variable is being updated concurrently by multiple threads in a non-thread safety manner. To solve this race-condition you need to use the reduction clause: #pragma omp parallel for reduction(+:result) num_threads(4)
for(i=0; i<NUM_STEP; i++)
    result += step*f(from+i*step);

A: I have added some comments to your example to hopefully make the behavior a bit clearer. List ml; //my_list
Element *e;

#pragma omp parallel  // e is shared for the parallel region
#pragma omp single
{
   for(e=ml->first;e;e=e->next)
     #pragma omp task  // since e is shared, all tasks will see the "same" e
     process(e);
} What happens is this (indicated by the comments above): you're declaring e outside of the scope of the parallel constructs.  As per the OpenMP specification, the variable will be shared across all the threads executing.  The single constructs then restricts execution to any one thread of the team ( e is still shared across all the threads, see https://www.openmp.org/spec-html/5.1/openmpsu113.html#x148-1600002.21.1 ). When the picked thread encounters the task construct, the OpenMP specification mandates that the created task from the task inherits the sharing attributes of the e variable (shared), so all created tasks will see the same variable and the picked thread may overwrite the e variable while it executes the for loop. That's where the firstprivate(e) comes in: List ml; //my_list
Element *e;

#pragma omp parallel  // e is shared for the parallel region
#pragma omp single
{
  for(e=ml->first;e;e=e->next)
  #pragma omp task firstprivate(e) // task now receives a private "copy" of e
    process(e);
} Here, the create tasks will have a private copy of e that is initialized with the current value of e as the picked thread progresses through the for loop. Another way to fix this would be this: List ml; //my_list

#pragma omp parallel  
#pragma omp single
{
  Element *e;   // e is thread-private inside the parallel region
  for(e=ml->first;e;e=e->next)
  #pragma omp task // task now receives a private "copy" of e w/o firstprivate
    process(e);
} Since in this example, the OpenMP specification mandates that the variable should be treated as if you specified firstprivate(e) (see https://www.openmp.org/spec-html/5.1/openmpsu113.html#x148-1610002.21.1.1 ).

A: There are some issues with your code, in the function main the iterations of the loop are not being assigned to threads as you wanted. Because you have added again the clause parallel to #pragma omp for , and assuming that you have nested parallelism disabled, which by default it is, each of the threads created in the outer parallel region will execute "sequentially" the code within that region. For more detail about it read this SO thread . Besides that this code: for (int j = 0; j < TRACE_COUNT; j++)
        {
            #pragma omp for
            for (int i = 0; i < FILTERLENGTH / 2; i++)
                d[j][i] = 0;

            for (int i = FILTERLENGTH / 2; i < TRACE_LENGTH + FILTERLENGTH / 2; i++)
                d[j][i] = rand() / fmax;
            for (i = TRACE_LENGTH + FILTERLENGTH / 2; i < TRACE_SPACE; i++)
                d[j][i] = 0;
        } can be improve by moving the #pragma omp for to the outer loop: #pragma omp for
        for (int j = 0; j < TRACE_COUNT; j++)
        {
            for (int i = 0; i < FILTERLENGTH / 2; i++)
                d[j][i] = 0;
            for (int i = FILTERLENGTH / 2; i < TRACE_LENGTH + FILTERLENGTH / 2; i++)
                d[j][i] = rand() / fmax;
            for (int i = TRACE_LENGTH + FILTERLENGTH / 2; i < TRACE_SPACE; i++)
                d[j][i] = 0;
        } And the scope of the parallel region should be reduced. Everything put together: #include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>

#define FILTERLENGTH 960
#define TRACE_LENGTH 16384
#define TRACE_COUNT 32
#define TRACE_SPACE (TRACE_LENGTH + FILTERLENGTH)

float f[FILTERLENGTH];
float d[TRACE_COUNT][TRACE_SPACE];
float out[TRACE_COUNT][TRACE_LENGTH];

void filter(int FL, float filt[FL], int NT, int TL, float traces[NT][TL + FL], float out[NT][TL]);

int main(int argc, char *argv[])
{
    #pragma omp parallel
    {
        float fmax = (float)RAND_MAX;
        #pragma omp for nowait
        for (int k = 0; k < FILTERLENGTH; k++)
            f[k] = k - (FILTERLENGTH - 1) / 2.0;

        #pragma omp for nowait
        for (int j = 0; j < TRACE_COUNT; j++)
        {    
            for (int i = 0; i < FILTERLENGTH / 2; i++)
                d[j][i] = 0;
            for (int i = FILTERLENGTH / 2; i < TRACE_LENGTH + FILTERLENGTH / 2; i++)
                d[j][i] = rand() / fmax;
            for (int i = TRACE_LENGTH + FILTERLENGTH / 2; i < TRACE_SPACE; i++)
                d[j][i] = 0;
        }
     }
     struct timeval start, stop, elapse;
     gettimeofday(&start, NULL);
     filter(FILTERLENGTH, f, TRACE_COUNT, TRACE_LENGTH, d, out);
     gettimeofday(&stop, NULL);
     timersub(&stop, &start, &elapse);

     fprintf(stderr, "Filter length\t%d\n", FILTERLENGTH);
     fprintf(stderr, "Trace length\t%d\n", TRACE_LENGTH);
     fprintf(stderr, "Trace count\t%d\n", TRACE_COUNT);
