int main(int argc, char *argv[])
{
    int x = 0;
    int y = 0;
    #pragma omp parallel shared(x, y) 
    {
        #pragma omp barrier
        for(x = 0, y = 0; x <= 500000; x++, y++) {
            printf("x: %d, y: %d\n", x, y);
        }
    }
