#define NTABLE  1000000
typedef size_t (hash_f)(size_t);

int main(int argc, char** argv) {
  Entry      table [NTABLE ]; 
  hash_f     hashes[NHASHES];
  omp_lock_t locks [NTABLE ]
  /* ... */
