A: Your main problem is that you declare your loop index i as shared . This leads every thread to use the same i in the evaluation. What you actually want to do with OpenMP is to divide the whole range of i in fractions and assign a different fraction to each thread. So, assign your i as private . Apart from this, you don't need to re-initialize x and sum in the parallel region. After fixing some irrelevant compilation errors, your code should look like this: #include<stdio.h>
#include <omp.h>
#define NUM_THREADS 2

int main (int argc, char **argv){

//Variables
int i=0, aux=0;
double step = 1.0/100000.0;
long num_steps = 100000;
double  x=0.0,
        pi=0.0,
        sum = 0.0;

 #pragma omp parallel shared(sum) private(i,x)
 {
    #pragma omp for
    for (i=0; i<num_steps; ++i) {
        x = (i-0.5)*step;

        #pragma omp critical
        sum += 4.0/(1.0+x*x);
    }
 }

 /* All threads join master thread and terminate */
 pi= step*sum;
 printf("PI value = %f\n", pi);

} Keep in mind that this is far from perfect in terms of performance, since every time you want to update the sum you pause the whole parallel region. A first step to make your code faster is by removing the critical part and declaring the sum as a reduction instead: #pragma omp parallel private(i,x)
 {
    #pragma omp for reduction(+:sum)
    for (i=0; i<num_steps; ++i) {
        x = (i-0.5)*step;

        sum += 4.0/(1.0+x*x);
    }
 }

