A: You can look up std::map elements either through the subscript operator [] or using the find method. std::map is not callable so you can't use the ds_lock(rid,cid) syntax. You map needs to use std::pair< unsigned int, unsigned int > as its key type. You would then be able to lock using omp_set_lock(&ds_lock[std::make_pair(rid,cid)]); However you will need to make sure that every used element of the map has been initialised in advance otherwise as std::map is not thread safe you will run into issues when the subscript operator automatically creates new elements, you would also need to call omp_init_lock on the newly created values. To ensure that omp_unset_lock is always called using the RAII pattern would be advisable. A fully working example fixing the above issues could look something like this: class omp_locker
{
  public:
    omp_locker( omp_lock_t& lock )
    : lock( lock )
    {
      omp_set_lock( &lock );
    }
    omp_locker( const omp_locker& ) = delete;
    omp_locker& operator=( const omp_locker& ) = delete;

    ~omp_locker()
    {
      omp_unset_lock( &lock );
    }

  private:
    omp_lock_t& lock;
};

std::map< std::pair< unsigned int, unsigned int >, omp_lock_t> ds_lock;
std::mutex ds_lock_mutex;

omp_lock_t& getLock( unsigned int rid, unsigned int cid )
{
  std::lock_guard lock( ds_lock_mutex );
  auto key = std::make_pair( rid, cid );
  auto it = ds_lock.find( key );
  if ( it == ds_lock.end() )
  {
    it = ds_lock.insert( it, std::make_pair( key, omp_lock_t() ) );
    omp_init_lock( it->second );
  }
  return it->second;
}

void Sparse_Matrix_FL::setValue(unsigned int rid, unsigned int cid, double value)
{
    omp_locker lock( getLock( rid, cid ) );
    std::map<unsigned int, double>::iterator str = data_Matrix[rid].begin();
    std::map<unsigned int, double>::iterator end = data_Matrix[rid].end();

    while (str->first != cid && str != end) str++;
    if (str != end)
        if (value != 0)
            str->second = value;
        else
            data_Matrix[rid].erase(str);
    else
        if (value != 0)
            data_Matrix[rid][cid] = value;
} You'll need to call omp_destroy_lock on every element of the std::map at the end of your program.

