A: A crude way to do it would be in OpenMP critical region, where you both set an "already set" flag and the shared variable.   As each thread enters the critical region, it tests the already set flag, and A finer-grained approach would be to use OpenMP locks; you can just have the first thread through set the lock after which other threads can't, and use that as your flag: #include <stdio.h>
#include <omp.h>

void setonce_thread(omp_lock_t *l, int input, int *sharedvar) {
    if (omp_test_lock(l)) {
        printf("Set lock with %d\n", input);
        *sharedvar = input;
    } else {
        printf("Could not set lock with %d\n", input);
    }
}

void setonce_crit(int input, int *setflag, int *sharedvar) {
#pragma omp critical
    {
        if ((*setflag) == 0) {
            (*setflag)++;
            *sharedvar = input;
            printf("Set in crit with %d\n", input);
        } else {
            printf("Could not set in crit with %d\n", input);
        }
    }
}


int main()
{
    omp_lock_t lck;
    int sharedvar1, sharedvar2;
    int setflag = 0;
    int input = 17;

    omp_set_nested(1);
    omp_set_num_threads(9);
    omp_init_lock(&lck);
#pragma omp parallel shared(lck, sharedvar1, sharedvar2, setflag, input) default(none) num_threads(3)
    {
#pragma omp for
        for (int i=0; i<3; i++) {
