i=12 k=3 j=14
i=12 k=3 j=15 So i = k * n; So your double loop it is equivalent to : for(int k=0; k<n; k++){
    int i = k * n;
    for(int j=i, l=0; j <i+n, l<n; j++,l++)
         result[k]+=matrix[j]*vector[l];
