int length_plus = length + 1;
std::vector<std::complex<double>> signalx(T); //source signal
std::vector<std::complex<double>> fundamental_freq(length); //just a vector of twiddle factors
std::vector<std::vector<std::complex<double>>> power_freq;

//some helper functions
void get_even_elements(std::vector<std::complex<double>> &inpt, std::vector<std::complex<double>> &out) {for (int i = 0; i < inpt.size()-1; i = i + 2) {out[i/2] = std::move(inpt[i]);}}
void get_odd_elements(std::vector<std::complex<double>> &inpt, std::vector<std::complex<double>> &out) {for (int i = 1; i < inpt.size(); i = i + 2) {out[i/2] = std::move(inpt[i]);}}
void attach(std::vector<std::complex<double>> &a, std::vector<std::complex<double>> &b, std::vector<std::complex<double>> &out) 
    {
    std::move(a.begin(), a.end(), out.begin());
    std::move(b.begin(), b.end(), out.begin()+a.size());
    }
void add_vectors(std::vector<std::complex<double>> &x, std::vector<std::complex<double>> &y, std::vector<std::complex<double>> &z) {for (int i = 0; i < x.size(); i++) {z[i] = x[i] + y[i];}}
void sub_vectors(std::vector<std::complex<double>> &y, std::vector<std::complex<double>> &x, std::vector<std::complex<double>> &z) {for (int i = 0; i < x.size(); i++) {z[i] = y[i] - x[i];}}

void dumb_get_even_elements(std::vector<double> &inpt, std::vector<double> &out) {for (int i = 0; i < inpt.size()-1; i = i + 2) {out[i/2] = inpt[i];}}
void dumb_get_odd_elements(std::vector<double> &inpt, std::vector<double> &out) {for (int i = 1; i < inpt.size(); i = i + 2) {out[i/2] = inpt[i];}}
void dumb_attach(std::vector<double> &a, std::vector<double> &b, std::vector<double> &out) {
    std::copy(a.begin(), a.end(), out.begin());
    std::copy(b.begin(), b.end(), out.begin()+a.size());
}

std::vector<double> dumb_fft(std::vector<double> x)
    {
        if (x.size() == 1) {return x;}
        else {
            int size = x.size();
            std::vector<double> e(size/2);
            std::vector<double> o(size/2);
            dumb_get_even_elements(std::ref(x),std::ref(e));
            dumb_get_odd_elements(std::ref(x),std::ref(o));
            std::vector<double> e1 = dumb_fft(e);
            std::vector<double> o1 = dumb_fft(o);
            std::vector<double> z(size);
            dumb_attach(std::ref(e1),std::ref(o1),std::ref(z));
            return z;
        }
    }

void compute_fft(std::vector<std::complex<double>> &x, int s) 
{
    std::vector<std::complex<double>> out(N);
    int m = std::exp2(s);

    #pragma omp parallel for
    for (int i = 0; i < N; i++) {
        int j = i % m;
        if (j < m/2) {
            int idx = j;
            std::complex<double> xr = power_freq[s][idx]*x[i+m/2];
            out[i] = x[i] + xr;
            }
        else {
            int idx = j-m/2;
            std::complex<double> xr = power_freq[s][idx]*x[i];
            out[i] = x[i-m/2] - xr;
            }
        }
    x = std::move(out);
    out.clear();
    out.shrink_to_fit();
}

//main loop
