        double denominator = std::exp2(s);
        std::complex<double> exponent = -2*3.14159265359*1i / denominator;
        fundamental_freq[s] = std::exp(exponent);
        }

    for (int s = 0; s < length_plus; s++) {
            power_freq.push_back({});
