A: You're trying to pass a number from one function ( bar or find_pivot ) to its caller ( foo or quicksort ). Using a global variable is a bad pattern for that. Change your tests that do not allow you to do that. Trying to work around that gives you unreadable, unmaintainable, and just painfully complicated code. In fact, it makes it so uselessly complicated that you can't even figure out how to write it yourself while the alternates are very simple. Compare this: int find_pivot(int *arr, int low, int high)
{
    return ...;
}

void quicksort(int *arr, int low, int high)
{
    ...
    int pivot_index = find_pivot(arr, low, high);
    quicksort(arr, low, pivot_index - 1);
    quicksort(arr, pivot_index + 1, high);
} Or using a pointer (typically if you have several values, or a complex value, to return): void find_pivot(int *arr, int low, int high, int *pivot_index)
{
    *pivot_index = ...;
}

void quicksort(int *arr, int low, int high)
{
    ...
    int pivot_index = -1;
    find_pivot(arr, low, high, &pivot_index);
    quicksort(arr, low, pivot_index - 1);
    quicksort(arr, pivot_index + 1, high);
} With the following (wrong!), which is close to what you have written: int pivot_index;

void find_pivot(int *arr, int low, int high)
{
    pivot_index = ...;
}

void quicksort(int *arr, int low, int high)
{
    ...
    find_pivot(arr, low, high);
    // What happens if two tasks call pivot_index simultaneously?
    // Which value will you get for quicksort? No way of knowing!
    quicksort(arr, low, pivot_index - 1);
    // pivot_index has changed value due to recursive quicksort() ! The next call is wrong!
    quicksort(arr, pivot_index + 1, high);
} Not only is it less readable (e.g. when reading quicksort, where does pivot_index come from?), but it also needs to be fixed (don't use this, it's terrible!): // can be set from several threads simultaneously
int pivot_index;
#pragma omp threadprivate(pivot_index)

void find_pivot(int *arr, int low, int high)
{
    pivot_index = ...;
}

void quicksort(int *arr, int low, int high)
{
    ...
    find_pivot(arr, low, high);
    // save value to protect from recursive calls
    int my_pivot_index = pivot_index;
    quicksort(arr, low, my_pivot_index - 1);
    quicksort(arr, my_pivot_index + 1, high);
