A: There are several ways to fix this.  The simplest is just to use the ordered clause.  See the code below.  However, this removes some of the parallelism.  A better way is to declare prviate dividors vectors (which I call dividors_private ) inside the parallel block so that each thread get's it's own private version and then write to the dividors vector in critical block.  The sorting is done on the private vectors in parallel.  A final sort is done on dividors in a single thread but since most of it is already sorted it goes fast.  See the second code below: The version of the code with ordered: #include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
#include "omp.h"

using namespace std;

vector<int> dividors;
int NUMBER = 1000;

bool ifContains(vector<int> dividors, int dividedNumber)
{
    for(int i=0; i<dividors.size(); i++)
    {
        if(dividors[i] == dividedNumber)
            return true;
    }

    return false;
}

void doStuff()
{
    int sqr = (int) sqrt(NUMBER);
    int sqrp1 = sqr + 1;

    #pragma omp parallel
    {
        #pragma omp for ordered
        for (int i = 1; i < sqrp1; i++)
        {

            if (NUMBER % i == 0)
            {
                #pragma omp ordered 
                {
                    dividors.push_back(i);
                    if (!ifContains(dividors, i))
                        dividors.push_back(i);

                    int dividednumber = NUMBER / i;

                    if (!ifContains(dividors, dividednumber))
                        dividors.push_back(dividednumber);
                }
            }
        }

    }
    sort(dividors.begin(), dividors.end());  
    for (int i = 0; i < dividors.size(); i++)
    {
        cout << dividors[i] << "\r\n";
    }
}

int main()
{
    doStuff();
    return 0;
} The version of the code which uses private dividors vectors #include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
#include "omp.h"

using namespace std;

vector<int> dividors;
int NUMBER = 1000;

bool ifContains(vector<int> dividors, int dividedNumber)
{
    for(int i=0; i<dividors.size(); i++)
    {
        if(dividors[i] == dividedNumber)
            return true;
    }

    return false;
}

void doStuff()
{
    int sqr = (int) sqrt(NUMBER);
    int sqrp1 = sqr + 1;

    #pragma omp parallel
    {
        vector<int> dividors_private;
        #pragma omp for nowait
        for (int i = 1; i < sqrp1; i++)
        {

            if (NUMBER % i == 0)
            {

                dividors_private.push_back(i);
                //printf("i %d\n", i);
                if (!ifContains(dividors_private, i))
                    dividors_private.push_back(i);

                int dividednumber = NUMBER / i;

                if (!ifContains(dividors_private, dividednumber))
                    dividors_private.push_back(dividednumber);
            }
        }
        sort(dividors_private.begin(), dividors_private.end());
        #pragma omp critical
        {
            dividors.insert(dividors.end(), dividors_private.begin(), dividors_private.end());
        }
    }
    sort(dividors.begin(), dividors.end()); 
    for (int i = 0; i < dividors.size(); i++) 
    {
        cout << dividors[i] << "\r\n";
    }
}

int main()
{
    doStuff();
