This may be because the data doesn't have good cache locality to begin with. Regardless, this is one way to study your problem. If you want better help than
this, you'll have to make an MWE of your own. You can alleviate some of the cache contention by reducing the number of threads you are using and specifying their affinity so that threads do not share the same L2/L3 caches (depending on your processor). More information is here . Minimum Working Example #include <algorithm>
#include <chrono>
#include <iostream>
#include <random>
#include <vector>

typedef std::vector< std::vector<int> > data_t;

data_t GenData(std::mt19937 &mt_rand, int vec_num, int vec_len){
  data_t data;
  data.reserve(vec_num);
  for(unsigned int i=0;i<vec_num;i++){
    data.emplace_back();
    data.back().reserve(vec_len);
    for(unsigned int i=0;i<vec_len;i++)
      data.back().emplace_back(mt_rand());
  }
  return data;
}

void SortSingle(data_t &data){
  for(auto &v: data)
    std::sort(v.begin(),v.end());
}

void SortMulti(data_t &data){
  #pragma omp parallel for default(none) shared(data)
  for(unsigned int i=0;i<data.size();i++)
    std::sort(data[i].begin(), data[i].end());
}

int main(int argc, char **argv){
  std::mt19937 mt_rand;

  typedef std::chrono::high_resolution_clock clock;

  std::cout<<"Generating data..."<<std::endl;
  auto data = GenData(mt_rand,1600,156250);

  std::cout<<"Sorting data..."<<std::endl;
  const auto start_time = clock::now();
  if(argv[1][0]=='s')
    SortSingle(data);
  else if (argv[1][0]=='m')
    SortMulti(data);
  else
    std::cout<<"Unknown sort type!"<<std::endl;
  const auto end_time = clock::now();

  const auto time_diff = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();

  std::cout<<"Time = "<<time_diff<<"s"<<std::endl;

  return 0;
}
