    for(int i = nx/2; i < nx ; i++){
        for(int j = 0; j < nyk; j++){           
             KX[j + nyk*i] =  2.* M_PI * ((i - nx) / Lx);    
        }
    } as previously you can also simplify (-i + 2.*k_counter) into i - nx .

