A: Running it without any changes its around 0.00775 sec To really see the benefits of the parallelism you need to increase your input size. Otherwise, the computation being performed in parallel will not be enough to overcome the additional overhead introduced with the parallelism (e.g., thread creation and synchronization) Let us start by declaring the variables closer to the scope where they will used. This will avoid having to explicitly add OpenMP pragmas to make those variables private ( i.e., private(it, k, i) ) double dphimax;
for (it=1;it<=itmax;it++){    
    dphimax=0.0;
    for (k=1;k<kmax;k++){
       for (i=1;i<imax;i++){
          dphi=(phi[i+1][k]+phi[i-1][k]-2.*phi[i][k])*dy2i
              +(phi[i][k+1]+phi[i][k-1]-2.*phi[i][k])*dx2i;
          dphi=dphi*dt;
          dphimax=max(dphimax,dphi);
          phin[i][k]=phi[i][k]+dphi;
      }
   }
    for (k=1;k<kmax;k++)
      for (i=1;i<imax;i++)
          phi[i][k]=phin[i][k];
