A: Short answer: no. The whole point of algorithms like inner_product is that they abstract the loop away from you. But in order to parallelise the algorithm you need to parallelise that loop – either via #pragma omp parallel for or via parallel sections. Both methods are inherently linked to the loop in the code structure so even if the loop were trivially parallelisable (which it might well be), you need to put the OpenMP pragmas inside the function to apply parallelism to it.
A: Following up on Hristo's comment, you can kind of do this by decomposing the arrays over threads, calling inner_product on each subarray, and then using some sort of reduction operation to combine the sub-results #include <iostream>
#include <numeric>
#include <omp.h>

#include <sys/time.h>
void tick(struct timeval *t);
double tock(struct timeval *t);

int main (int argc, char **argv) {
  const long int nelements=1000000;
  long int *a = new long int[nelements];
  long int *b = new long int[nelements];
  int nthreads;
  long int sum = 0;
  struct timeval t;
  double time;

  #pragma omp parallel for
  for (long int i=0; i<nelements; i++) {
        a[i] = i+1;
        b[i] = 1;
  }

  tick(&t);
  #pragma omp parallel 
  #pragma omp single
  nthreads = omp_get_num_threads();

  #pragma omp parallel default(none) reduction(+:sum) shared(a,b,nthreads) 
  {
       int tid = omp_get_thread_num();
       int nitems = nelements/nthreads;
       int start = tid*nitems;
       int end   = start + nitems;
       if (tid == nthreads-1) end = nelements;

       sum += std::inner_product( &(a[start]), a+end, &(b[start]), 0L);
  }
  time = tock(&t);

  std::cout << "using omp: sum = " << sum << " time = " << time << std::endl;

  delete [] a;
  delete [] b;



  a = new long int[nelements];
  b = new long int[nelements];
  sum = 0;

  for (long int i=0; i<nelements; i++) {
        a[i] = i+1;
        b[i] = 1;
  }
  tick(&t);
  sum = std::inner_product( a, a+nelements, b, 0L);
  time = tock(&t);

  std::cout << "single threaded: sum = " << sum << " time = " << time << std::endl;

  std::cout << "correct answer: sum = " << (nelements)*(nelements+1)/2 << std::endl ;

  delete [] a;
  delete [] b;

  return 0;
}

void tick(struct timeval *t) {
    gettimeofday(t, NULL);
}

/* returns time in seconds from now to time described by t */
double tock(struct timeval *t) {
    struct timeval now;
    gettimeofday(&now, NULL);
    return (double)(now.tv_sec - t->tv_sec) + ((double)(now.tv_usec - t->tv_usec)/1000000.);
} Running this gets better speedup than I would have expected: $ for NT in 1 2 4 8; do export OMP_NUM_THREADS=${NT}; echo; echo "NTHREADS=${NT}";./inner; done

