A: You have race conditions with your count variable where multiple threads can try to update it at the same time. The easy fix is to use an OpenMP reduction() clause to give each thread a private copy of the variable and have them all get added up properly: #include <time.h>
#include <stdio.h>
#include <stdbool.h>

int main(void)
{
    clock_t start = clock();
    int count = 1;
#pragma omp parallel for schedule(static,1) num_threads(2) reduction(+:count)
    for (int x = 3; x <= 5000000; x+=2)
    {
        bool flag = false;
        if (x == 2 || x == 3)
            count++;
        else if (x % 2 == 0 || x % 3 == 0)
            continue;
        else
        {
            for (int i = 5; i * i <= x; i += 6)
            {
                if (x % i == 0 || x % (i + 2) == 0)
                {
                    flag = true;
                    break;
                }
            }
            if (!flag)
                count++;
        }
    }
    clock_t end = clock();
    printf("The execution took %f ms\n", (double)end - start / CLOCKS_PER_SEC);
    printf("%d\n", count);
} This outputs 348513 (Verified as the right number through other software). Also note cleaned up headers and moving some variable declarations around to avoid the need for a private() clause. You could also make count an atomic int, but that's slower than using reduction() in my testing.
