A: Here's some OpenMP code I put together to find the intersection of two sorted sets. It's possible to do this without a critical section when merging the results (as well as merge them sorted in parallel) but I did not do that here. It's probably possible to do this with SIMD (efficiently) as well. I would do that explicitly using intrinsic or a SIMD vector class. size_t intersect_scalar_omp(int *A, int *B, size_t s_a, size_t s_b, int *C) {
    size_t counter = 0;
    #pragma omp parallel
    {
        size_t i_a = 0, i_b = 0;
        size_t aend = s_a, bend = s_b;
        size_t counter_private = 0;
        int ithread = omp_get_thread_num();
        int nthreads = omp_get_num_threads();   

        if (s_a > s_b) {
            i_a = ithread*s_a / nthreads;
            aend = (ithread + 1)*s_a / nthreads;            
        }
        else {
            i_b = ithread*s_b / nthreads;
            bend = (ithread + 1)*s_b / nthreads;
        }
        int *C_private = new int[aend > bend ? aend : bend];
        while (i_a < aend && i_b < bend) {
            if (A[i_a] < B[i_b]) {
                i_a++;
            }
            else if (B[i_b] < A[i_a]) {
                i_b++;
            }
            else {
                C_private[counter_private++] = A[i_a];
                i_a++; i_b++;
            }
        }
        #pragma omp critical
        {
            memcpy(&C[counter], C_private, sizeof(int)*counter_private);
            counter += counter_private;
        }
        delete[] C_private;
    }
    std::sort(C, C + counter);
    return counter;
}

A: The problem is that prgb is a shared pointer and incrementing it in each thread without any data protection leads to data races. Instead, your code should look like similar to this: #pragma omp parallel for schedule(static)
for (int iPixel=0; iPixel < numPixels; iPixel++ ) {
   RGBTRIPLE *ppixel = prgb + iPixel;

   ppixel->rgbtGreen = ppixel->rgbtGreen * _contrastPower + _brightnessPower;
   ppixel->rgbtBlue  = ppixel->rgbtBlue  * _contrastPower + _brightnessPower;
   ppixel->rgbtRed   = ppixel->rgbtRed   * _contrastPower + _brightnessPower;  

   if(ppixel->rgbtGreen>255) ppixel->rgbtGreen = 255;
   if(ppixel->rgbtBlue>255)  ppixel->rgbtBlue  = 255;
   if(ppixel->rgbtRed>255)   ppixel->rgbtRed   = 255;
} The algorithm is memory bound on modern CPUs, therefore do not expect performance to be linearly proportional to the number of threads if the image data does not fit entirely in the CPU cache.

A: Any solution I can think of involves using an omp_lock_t instead of the critical construct and a RAII class managing the omp_lock_t ownership: class LockGuard {
public:  
    explicit LockGuard(omp_lock_t& lock) : m_lock(lock){
        omp_set_lock(&m_lock);
    }

    ~LockGuard() {
        omp_unset_lock(&m_lock);
    }

private:
  omp_lock_t& m_lock;
}; Then you can either modify the code you already have into something like: MyType & retrieve() {
    LockGuard guard(mydeque_lock);
    auto b = mydeque.front();
    mydeque.pop_front();
    return b;
} or better, write your own thread-safe container that aggregates the lock and the std::deque : template<class T>
class MtLifo {
public:
    MtLifo() {
       omp_init_lock(&m_lock);
    }

    typename std::deque<T>::reference front_and_pop() {
        LockGuard guard(m_lock);
        auto b = m_stack.front();
        m_stack.pop_front();
        return b;
    }

    void push_front(const T& value) {
        LockGuard guard(m_lock);
        m_stack.push_front(value);
    }


    ~MtLifo() {
        omp_destroy_lock(&m_lock);
    }

private:
   std::deque<T> m_stack;
   omp_lock_t m_lock;
}
