A: You are paying the overheads of the atomic operation and task creation and management. You can get a better speedup with a simpler parallel for with reduction, namely: #pragma omp parallel default(none) shared(n) reduction( + : sum ) 
for ( i = 0; i < n; i++) {
     double factor = (i % 2 == 0) ? 1.0 : -1.0;
     sum += factor / (2 * i + 1);
} We can slightly improve the sequential code by separating beforehand the odds from the evens: #pragma omp parallel default(none) shared(n, sum) nowait
{
     #pragma omp for reduction( + : sum ) 
     for (int i = 0; i < n; i+=2 ) {
        sum += 1.0 / (2 * i + 1);
    }
    #pragma omp for reduction( + : sum ) 
    for (int i = 1; i < n; i += 2) {
        sum += -1.0 / (2 * i + 1);
    }
} You can improve it further by having a single loop for performing the even and odds computation for each iteration of that loop. You do not need to make the 'i' from the loop private , it will be implicitly private in OpenMP. If you really have to use tasks, you can try to minimize the synchronization overhead by replicating the variable sum among threads, and reduce it manually at the end of the parallel region , (I am assuming n >= 2 and n being even just for simplicity sake): double sum[total_threads];

#pragma omp parallel default(none) shared(n, sum)
{
    int threadID = omp_get_thread_num();
    sum[threadID] = 0.0;
    #pragma omp single
    {
        for ( i = 0; i < n; i+=2) {
            #pragma omp task
            {
                sum[threadID] += 1.0 / (2 * i + 1);
                sum[threadID] += -1.0 / (2 * (i + 1) + 1);
            }
        }
    }
  }

double master_sum = 0.0;
for(int i = 0; i < total_threads; i++)
    master_sum += sum[i]; If you are using a C compiler that supports OpenMP 4.5 you can use a more sophisticated constructor, namely taskloop Construct , and combined it with the reduction of the variable sum .

