A: The problem seems to be that the private attribute attached to the lnorm variable by the omp parallel block conflicts with the requirements imposed by the OpenMP reduction() clause on its argument variable (even though lnorm is not private with respect to the nested omp simd block to which the reduction() clause applies). You can try solving that problem by extracting the lnorm calculation code into a function of its own: template <typename FT, int veclen>
inline double compute_res_and_lnorm(FT *res,
                           FT *x,
                           FT *y,
                           int low,
                           int hi)
{
    double lnorm = 0;

#pragma omp simd aligned(res, x, y : veclen) reduction(+ : lnorm)
    for (int i = low; i < hi; i++) {
        res[i] = x[i] - y[i];
        double tmpd = (double)res[i];
        lnorm += (tmpd * tmpd);
    }
    return lnorm;
}

