A: Edit:  I thought of a way to do this using the preprocessor.  This fixes the problem of duplicate code at the expense of making the compiling and linking slightly more complicated.  It uses the feature that if OpenMP is not enabled in the compiler then the OpenMP constructs are ignored. #include <stdlib.h>

void setQueen(int* x, int y, int z) {
   /*code*/
}
#if defined _OPENMP
void solve_parallel(const int size)
#else
void solve_serial(const int size)
#endif
{
    int i;
    #pragma omp parallel for      
    for(i = 0; i < size; i++) {
        int *queens = (int*)malloc(sizeof(int)*size);
        setQueen(queens, 0, i);
